window.ScripturaLexicons.BDAG_PART_0130 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exilaskomai-bdag\" data-source=\"BDAG\" data-search=\"ἐξιλάσκομαι exiláskomai verbo médio aplacar; obter favor; propiciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξιλάσκομαι</td><td>verbo médio</td><td>aplacar; obter favor; propiciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hexis-bdag\" data-source=\"BDAG\" data-search=\"ἕξις, εως, ἡ héxis substantivo feminino estado; maturidade; habilidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕξις, εως, ἡ</td><td>substantivo feminino</td><td>estado; maturidade; habilidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-existemi-bdag\" data-source=\"BDAG\" data-search=\"ἐξίστημι exístēmi verbo confundir; assombrar; espantar; perder a razão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξίστημι</td><td>verbo</td><td>confundir; assombrar; espantar; perder a razão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exischyo-bdag\" data-source=\"BDAG\" data-search=\"ἐξισχύω exischýō verbo ser inteiramente capaz; ter força suficiente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξισχύω</td><td>verbo</td><td>ser inteiramente capaz; ter força suficiente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exodos-bdag\" data-source=\"BDAG\" data-search=\"ἔξοδος, ου, ἡ éxodos substantivo feminino saída; êxodo; partida; morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξοδος, ου, ἡ</td><td>substantivo feminino</td><td>saída; êxodo; partida; morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoideo-bdag\" data-source=\"BDAG\" data-search=\"ἐξοιδέω exoidéō verbo inchar; ficar inchado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξοιδέω</td><td>verbo</td><td>inchar; ficar inchado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoisousi-bdag\" data-source=\"BDAG\" data-search=\"ἐξοίσουσι exoísousi forma verbal; remissão ver ἐκφέρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξοίσουσι</td><td>forma verbal; remissão</td><td>ver ἐκφέρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exolethreuo-bdag\" data-source=\"BDAG\" data-search=\"ἐξολεθρεύω exolethreúō verbo destruir inteiramente; exterminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξολεθρεύω</td><td>verbo</td><td>destruir inteiramente; exterminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exomoioo-bdag\" data-source=\"BDAG\" data-search=\"ἐξομοιόω exomoióō verbo tornar completamente semelhante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξομοιόω</td><td>verbo</td><td>tornar completamente semelhante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exomologeo-bdag\" data-source=\"BDAG\" data-search=\"ἐξομολογέω exomologéō verbo consentir; confessar; professar; louvar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξομολογέω</td><td>verbo</td><td>consentir; confessar; professar; louvar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exomologesis-bdag\" data-source=\"BDAG\" data-search=\"ἐξομολόγησις, εως, ἡ exomológēsis substantivo feminino louvor; profissão; possível oração de graças BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξομολόγησις, εως, ἡ</td><td>substantivo feminino</td><td>louvor; profissão; possível oração de graças</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exon-bdag\" data-source=\"BDAG\" data-search=\"ἐξόν exón forma flexionada; remissão ver ἔξεστιν 4 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξόν</td><td>forma flexionada; remissão</td><td>ver ἔξεστιν 4</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exorizo-bdag\" data-source=\"BDAG\" data-search=\"ἐξορίζω exorízō verbo excluir; banir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξορίζω</td><td>verbo</td><td>excluir; banir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exorkizo-bdag\" data-source=\"BDAG\" data-search=\"ἐξορκίζω exorkízō verbo conjurar; exorcizar; tomar juramento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξορκίζω</td><td>verbo</td><td>conjurar; exorcizar; tomar juramento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exorkistes-bdag\" data-source=\"BDAG\" data-search=\"ἐξορκιστής, οῦ, ὁ exorkistḗs substantivo masculino exorcista BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξορκιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>exorcista</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exorysso-bdag\" data-source=\"BDAG\" data-search=\"ἐξορύσσω exorýssō verbo arrancar; extrair; escavar através BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξορύσσω</td><td>verbo</td><td>arrancar; extrair; escavar através</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoudeneo-exoudenoo-bdag\" data-source=\"BDAG\" data-search=\"ἐξουδενέω/ἐξουδενόω exoudenéō / exoudenóō verbos; variantes gráficas desprezar; tratar com escárnio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουδενέω/ἐξουδενόω</td><td>verbos; variantes gráficas</td><td>desprezar; tratar com escárnio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exoutheneo-exouthenoo-bdag\" data-source=\"BDAG\" data-search=\"ἐξουθενέω/ἐξουθενόω exouthenéō / exouthenóō verbos; variantes gráficas desprezar; rejeitar com desprezo; maltratar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουθενέω/ἐξουθενόω</td><td>verbos; variantes gráficas</td><td>desprezar; rejeitar com desprezo; maltratar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exouthenema-bdag\" data-source=\"BDAG\" data-search=\"ἐξουθένημα, ατος, τό exouthénēma substantivo neutro coisa desprezada; objeto de desprezo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουθένημα, ατος, τό</td><td>substantivo neutro</td><td>coisa desprezada; objeto de desprezo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exousia-bdag\" data-source=\"BDAG\" data-search=\"ἐξουσία, ας, ἡ exousía substantivo feminino direito; capacidade; autoridade; domínio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξουσία, ας, ἡ</td><td>substantivo feminino</td><td>direito; capacidade; autoridade; domínio</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-exilaskomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξιλάσκομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exiláskomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξιλάσκομαι</span> (ver <span class=\"greek\">ἱλάσκομαι</span>); futuro <span class=\"greek\">ἐξιλάσομαι</span>; primeiro aoristo <span class=\"greek\">ἐξιλασάμην</span>; futuro passivo, terceira pessoa do singular, <span class=\"greek\">ἐξιλασθήσεται</span>, LXX. Quando alguém procura obter a boa vontade de outrem, o verbo pode traduzir-se por «aplacar» (uma pessoa: PTebt 750, 16 [séc. II a.C.]); nesse sentido, <span class=\"greek\">ἐ</span>. aproxima-se de <span class=\"greek\">θεραπεύειν</span>, como em Thu. 1, 137, 3, <span class=\"greek\">τινὰ</span> <span class=\"greek\">χρημάτων</span> <span class=\"greek\">δόσει</span>. Em toda a literatura grega, a divindade é o objeto mais frequente (já no oráculo de Hdt. 7, 141, <span class=\"greek\">Δία</span>; X., Cyr. 7, 2, 19, <span class=\"greek\">Ἀπόλλωνα</span>; Menand., Fgm. 754, 6 Kö. [=544, 6, p. 164 Kock], <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; Polyb. 3, 112, 19; Diod S 1, 59, 2, <span class=\"greek\">θυσίαις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>; 14, 77, 4, <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>; 20, 14, 3; Strabo 4, 1, 13; Dio Chrys. 15 [32], 77; Ael. Aristid. 46, 3 K. = 3, p. 30 D.; Zc 7:2; 8:22; Ez 16:63; PsSol 3:8; TestLevi 3:5, <span class=\"greek\">πρὸς</span> <span class=\"greek\">κύριον</span>; JosAs 28:5; EpArist 316; Philo, Poster. Cai. 72 [após Lv 16:10]; Jos., Bell. 5, 19; SibOr 7, 30. — Ver <span class=\"greek\">ἱλάσκομαι</span> e <span class=\"greek\">ἵλεως</span>). Em 1Cl 7:7 e Hv 1, 2, 1, o pecado torna necessário o apaziguamento de Deus (cf. IG II², 1366, 15s = SIG 1042 [séc. II/III d.C.], <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ὀφειλέτω</span> <span class=\"greek\">Μηνὶ</span> <span class=\"greek\">Τυράννῳ</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">δύνηται</span> <span class=\"greek\">ἐξειλάσασθαι</span> [= «que tal pessoa seja considerada culpada, perante Men Soberano, de uma ofensa para a qual não há expiação»]; ver também Just., A I, 50, 2, <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνόμοις</span> <span class=\"greek\">ἐξιλάσεται</span> [por Is 53:12]). — TW.</p></section></article>\n<article id=\"entry-hexis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕξις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦héxis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἕξις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (pré-socráticos e outros; IIasos 98, 16 [séc. I a.C.]; POxy 2190, 16 [séc. I d.C.]; LXX; com vários sentidos: «estado físico ou mental, proficiência, habilidade»). No único lugar em que é empregado na literatura considerada, refere-se a um estado de maturidade: «maturidade» (cf. «característica», Philo, Leg. All. 1, 10, 3; «habilidade, proficiência»: Polyb. 10, 47, 7; 21, 9, 1; Diod S 2, 29, 4; prólogo de Sir 1:11; IIasos, acima; EpArist 121). <span class=\"greek\">αἰσθητήρια</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἕ</span>. <span class=\"greek\">γεγυμνασμένα</span>, «[o alimento sólido é para os adultos que], por causa de seu estado de maturidade, [têm] os sentidos exercitados [para discernir entre o bem e o mal]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:14</a> (assim JLee, NovT 39, 1997, 151–76, especialmente p. 166; MKiley, CBQ 42, 1980, 501–3: «estado característico [dos adultos]»). À exceção de ASouter, A Pocket Lexicon to the Gk. NT, 1916 (ver s.v. «condição, estado»), os léxicos do grego neotestamentário, bem como as versões e traduções do NT, geralmente traduzem <span class=\"greek\">ἕξ</span>. nessa passagem por «exercício, prática». — DELG, s.v. 1 <span class=\"greek\">ἔχω</span>. TW. Sv.</p></section></article>\n<article id=\"entry-existemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξίστημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exístēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξίστημι</span>, com a forma alternativa do grego comum <span class=\"greek\">ἐξιστάνω</span> (B-D-F §93; Mlt-H. 241), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:9</a> (variante <span class=\"greek\">ἐξιστῶν</span>, de <span class=\"greek\">ἐξιστάω</span>); futuro <span class=\"greek\">ἐκστησώ</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξέστησα</span>; segundo aoristo <span class=\"greek\">ἐξέστην</span>; perfeito <span class=\"greek\">ἐξέστακα</span>; particípio [intransitivo] <span class=\"greek\">ἐξεστώς</span> (Jz 4:21 B) e <span class=\"greek\">ἐξεστηκυῖα</span>, 1Km 4:13; mais-que-perfeito, segunda pessoa do singular, <span class=\"greek\">ἐξεστηκεῖς</span> (TestJob 39:13). Voz média: imperfeito <span class=\"greek\">ἐξιστάμην</span>; perfeito <span class=\"greek\">ἐξίσταμαι</span>. Voz passiva: aoristo, terceira pessoa do singular, <span class=\"greek\">ἐξεστάθη</span> (Jz 5:4 A). Tanto no uso transitivo quanto no intransitivo, a ideia central é o envolvimento num estado ou condição de consternação.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Uso transitivo. Sentido primário: «mudar, deslocar» (Aristot. e outros; Just., D. 67, 3, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκστήσετε</span> <span class=\"greek\">με</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προκειμένων</span>, «não me afastareis da posição que sustento acerca dessas questões»); daí, fazer alguém entrar num estado em que as coisas parecem ter pouco ou nenhum sentido: «confundir, maravilhar, assombrar» (assim, muitas vezes, com palavras adicionais: <span class=\"greek\">τινὰ</span> <span class=\"greek\">φρενῶν</span>, Eur., Bacch. 850; <span class=\"greek\">τινὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρονεῖν</span>, X., Mem. 1, 3, 12; <span class=\"greek\">τινὰ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">διανοίαις</span>, Polyb. 11, 27, 7; mas também com acusativo simples, como a seguir). <span class=\"greek\">τινά</span>, «alguém» (Musonius, p. 35, 12, <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξιστάντα</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span>; Lucian, Dom. 19; Stob., Ecl. III 517, 15, <span class=\"greek\">οἶνος</span> <span class=\"greek\">ἐξέστησέ</span> <span class=\"greek\">με</span>; Js 10:10; Jz 4:15; 2Km 22:15 e outros; Jos., Bell. 3, 74; TestBenj 3:3, variante; Hippol., Ref. 6, 40, 2; 9, 11, 1), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:22</a>. De um feiticeiro: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Σαμαρείας</span>, «a nação da Samaria», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:9</a>, 11.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Uso intransitivo (segundo aoristo e perfeito ativos; todas as formas médias). Do sentido «separar-se de alguma coisa ou perder alguma coisa» (Empedocles e outros), desenvolve-se o sentido psicológico (o único sentido do intransitivo na literatura considerada; para perturbação física, ver TestZeb 2:5; cf. Orig., C. Cels. 3, 70, 20): «estar fora de seu estado mental normal».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Da incapacidade de raciocinar normalmente: «perder a razão, estar fora de si» (assim Eur. [por exemplo, Bacch. 359 e outros, no sentido de «sair de sua própria mente»; VLeinieks, The City of Dionysos, 1996, 111], Isocr. e outros, geralmente [como Jos., Ant. 10, 114] com <span class=\"greek\">τῶν</span> <span class=\"greek\">φρενῶν</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρονεῖν</span> ou complemento semelhante. Sem complemento, por exemplo, Aristot., HA 6, 22, p. 577a, 12, <span class=\"greek\">ἐξίσταται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαίνεται</span>; Menand., Sam. 279 S. [64 Kö.], <span class=\"greek\">ἐξέστηχ</span>’ <span class=\"greek\">ὅλως</span>; Dio Chrys. 80 [30], 6; Is 28:7; TestJob 35s e 39; Philo, Ebr. 146; Orig., C. Cels. 7, 4, 14 [sobre a Pítia]; Did., Gen. 230, 14). <span class=\"greek\">ἔλεγον</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐξέστη</span>, «diziam: Ele perdeu o juízo», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:21</a> (cf. Irish Eccl. Record 64, 1944, 289–312; 65, 1945, 1–5; 6–15; JSteinmueller, CBQ 4, 1942, 355–59; HWansbrough, NTS 18, 1971/72, 233–35; bibliografia também em <span class=\"greek\">παρά</span> A 3b, fim). Provavelmente irônico: <span class=\"greek\">εἴτε</span> <span class=\"greek\">ἐξέστημεν</span> … <span class=\"greek\">εἴτε</span> <span class=\"greek\">σωφρονοῦμεν</span>, «se estivemos fora de nós …; se estamos em nosso juízo perfeito», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:13</a> (CBruston, RTQR 18, 1908, 344ss). Contudo, na literatura considerada, é mais frequente o sentido enfraquecido:</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> «Ficar maravilhado, espantar-se», acerca do sentimento de admiração mesclado de temor, causado por acontecimentos milagrosos, extraordinários ou difíceis de entender (Philippides Com. [séc. IV/III a.C.], Fgm. 27 K., <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἐξέστην</span> <span class=\"greek\">ἰδών</span> = «fiquei assombrado quando vi [os vasos preciosos]»; Gn 43:33; Rt 3:8; 1Km 14:15 e outros; ApcSed 10:6; cf. Iren. 1, 2, 3 [Harv. I 17, 11]), MPol 12:1. <span class=\"greek\">ἐξίσταντο</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχλοι</span> (cf. Êx 19:18; Lv 9:24), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:23</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:12</a>. <span class=\"greek\">ἐξέστησαν</span> <span class=\"greek\">ἐκστάσει</span> <span class=\"greek\">μεγάλῃ</span> (cf. Gn 27:33), «ficaram inteiramente assombrados», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:42</a>. <span class=\"greek\">λίαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐξίσταντο</span>, «ficaram profundamente espantados consigo mesmos», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:51</a>. — <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:56</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:7</a> (com <span class=\"greek\">θαυμάζω</span>), 12 (com <span class=\"greek\">διαποροῦμαι</span>); 8:13; 9:21; 10:45 (seguido de <span class=\"greek\">ὅτι</span>); 12:16. <span class=\"greek\">ἐξίσταντο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">συνέσει</span> <span class=\"greek\">αὐτοῦ</span>, «maravilhavam-se de sua inteligência», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:47</a> (<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, como em Wsd 5:2; Os 3:5). Do céu, B 11:2 (Jr 2:12). (Ver <span class=\"greek\">ἵστημι</span>). — M-M. EDNT. TW. Spicq.</p></section></article>\n<article id=\"entry-exischyo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξισχύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exischýō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξισχύω</span> (ver <span class=\"greek\">ἰσχύω</span>); futuro, segunda pessoa do singular, <span class=\"greek\">ἐξισχύσεις</span>, Sir 7:6, códice B; primeiro aoristo <span class=\"greek\">ἐξίσχυσα</span> (Strabo 17, 1, 3; Vett. Val. 288, 12). «Ser plenamente capaz de fazer ou experimentar alguma coisa, ser capaz, ser bastante forte, estar em condições», seguido de infinitivo (Proclus sobre Pla., Cratyl. p. 65, 19 Pasqu.; POxy 1120, 7; BGU 275, 11; PAnt 35 II, 13; Sir 7:6, variante; Jos., Bell. 1, 451), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:18</a>. — DELG, s.v. <span class=\"greek\">ἰσχύς</span>. M-M.</p></section></article>\n<article id=\"entry-exodos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξοδος, ου, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxodos⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξοδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">ὁδός</span>; «saída, afastamento», autores trágicos e outros; inscrições, papiros, LXX; PsSol 4:14; TestSol 25:5; Philo, Joseph., Test12Patr; Just.; Mel., P. 1, 3).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Movimento de uma região geográfica para outra: «partida, percurso, trajeto».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Da partida coletiva ou êxodo do Egito (Sl 104:38; 113:1; Philo, Mos. 2, 248; Jos., Ant. 5, 72, C. Ap. 223; TestSim 9; Mel., P. 1:3): «a partida/o êxodo» [bem conhecido], <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> De pedras e de seu destino no deslocamento de um lugar para outro: «percurso, destino, destinação», em imagens apocalípticas, Hv 3, 4, 3 (pergunta do Pastor: «Para onde vão as pedras?»).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Partida do convívio dos vivos, eufemismo (aquele que morre tem a ilusão de uma escolha, e o enlutado encontra consolo nesse tema) para «morte» (Soph., Oed. Rex 959, 1372; Tr. 4; Wsd 3:2; 7:6; Philo, Virt. 77; Jos., Ant. 4, 189, <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span>; TestNapht 1:1. Cf. Epict. 4, 4, 38; Just., D. 105, 3; 5). <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐμὴν</span> <span class=\"greek\">ἔ</span>., «depois da minha morte», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:15</a> (cf. o testamento de Abraão, bispo de Hermonthis, PLond I, 77, 57, p. 234, <span class=\"greek\">κελεύω</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐμὴν</span> <span class=\"greek\">ἔξοδον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βίου</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔ</span>., <span class=\"greek\">ἣν</span> <span class=\"greek\">ἤμελλεν</span> <span class=\"greek\">πληροῦν</span>, «sua partida, que estava para realizar», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:31</a>. — M-M. TW.</p></section></article>\n<article id=\"entry-exoideo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοιδέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exoidéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξοιδέω</span>; infinitivo do primeiro aoristo <span class=\"greek\">ἐξοιδῆσαι</span> (<span class=\"greek\">οἰδέω</span>, «inchar»; Eur., Polyb. e outros): «inchar, ficar inchado». <span class=\"greek\">τὰ</span> <span class=\"greek\">βλέφαρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">αὐτου</span> <span class=\"greek\">φασί</span> <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">ἐξοιδῆσαι</span>, <span class=\"greek\">ὡς</span> …, «diziam que suas pálpebras ficaram tão inchadas que …», Papias (3:2). — DELG, s.v. <span class=\"greek\">οἰδέω</span>.</p></section></article>\n<article id=\"entry-exoisousi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοίσουσι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exoísousi⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξοίσουσι</span>: ver <span class=\"greek\">ἐκφέρω</span>.</p></section></article>\n<article id=\"entry-exolethreuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξολεθρεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exolethreúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξολεθρεύω</span>; futuro <span class=\"greek\">ἐξολεθρεύσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξωλέθρευσα</span>. Passivo: primeiro futuro <span class=\"greek\">ἐξολεθρευθήσομαι</span>; aoristo <span class=\"greek\">ἐξωλεθρεύθην</span>, LXX (Crito [início do séc. II d.C.]: 200 Fgm. 2 Jac.; TestSol 6:2 D, <span class=\"greek\">ἐξολόθρευσον</span>; JosAs, cap. 11, códice A [p. 53, 19 Bat.], <span class=\"greek\">ἐξολοθρευθῆναι</span>; SibOr 5, 454; 12, 102; 14, 107; Just., D. 131, 5, <span class=\"greek\">ἐξολοθρευθήσεσθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span>; Test12Patr; Pel.-Leg. p. 23, 15; 24, 18; PCairMasp 2 III, 28 [séc. VI d.C.]. — Como variante de leitura em Plut., Dio 965 [18, 9] Ziegler; Jos., Ant. 8, 270 N.; e SibOr 3, 309 G. Sobre a grafia [<span class=\"greek\">ἐξολο</span>-] da palavra, ver B-D-F §32, 1; Thackeray, p. 87s; Mlt-H. 71): «eliminar pela destruição, destruir completamente, exterminar». <span class=\"greek\">τινά</span>, «alguém», 1Cl 53:3 (Dt 9:14). <span class=\"greek\">τὶ</span>, «alguma coisa»: <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χείλη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δόλια</span>, «todos os lábios mentirosos», 1Cl 15:5 (Sl 11:4). <span class=\"greek\">τὶ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, «algo de alguma coisa», 1Cl 22:6 (Sl 33:17). Passivo: B 7:3 (Lv 23:29); <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, «do povo», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:23</a> (Lv 23:29); <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, 1Cl 14:4 (Sl 36:38, mas sem <span class=\"greek\">ἀπό</span> <span class=\"greek\">τ</span>.; quanto à combinação <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span>, cf. 1Macc 2:40; Jdth 6:2); <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:12</a>, variante (Sl 33:17). — DELG, s.v. <span class=\"greek\">ὄλλυμι</span>. M-M. TW.</p></section></article>\n<article id=\"entry-exomoioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξομοιόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exomoióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξομοιόω</span>; particípio aoristo <span class=\"greek\">ἐξομοιωθέντες</span> (Just., D. 44, 2; 45, 4); «tornar exatamente igual ou semelhante» (Hdt. e outros; Sextus 381). Passivo com sentido ativo: «tornar-se inteiramente igual ou semelhante, assemelhar-se plenamente» (autores trágicos e outros; 2Macc 4:16; Philo, Aet. M. 44; Just.); <span class=\"greek\">τινί</span>, «a alguém» (Epict. 1, 2, 18; 2, 14, 12; Socrat., Ep. 6, 4; Just., D., referências acima, também 122, 2). <span class=\"greek\">τέλεον</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐξομοιοῦσθε</span>, «finalmente vos tornais exatamente semelhantes a eles», Dg 2:5. — DELG, s.v. <span class=\"greek\">ὁμός</span>.</p></section></article>\n<article id=\"entry-exomologeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξομολογέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exomologéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξομολογέω</span> (ver o verbete seguinte e <span class=\"greek\">ὁμολογέω</span>); primeiro aoristo <span class=\"greek\">ἐξωμολόγησα</span>; futuro médio <span class=\"greek\">ἐξομολογήσομαι</span>; aoristo médio <span class=\"greek\">ἐξωμολογησάμην</span>, LXX (atestável desde o século III a.C. — Mitt-Wilck. II/2, 20, 18; 37, 17 — PHib 30, 18 [300–271 a.C.]; também LXX, pseudepígrafos, Philo, Joseph.).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Indicar aceitação de uma oferta ou proposta: «prometer, consentir», na voz ativa, absolutamente, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:6</a> (a voz ativa é encontrada tão raramente [talvez Alex. Aphr., An. Mant. II 1, p. 168, 15] quanto a passiva [talvez SIG 685, 95]).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Fazer o reconhecimento de um erro ou pecado: «confessar, admitir», na voz média (Plut., Eum. 594 [17, 7]; Anton. 943 [59, 3], <span class=\"greek\">τ</span>. <span class=\"greek\">ἀλήθειαν</span>; Stoic. Repugn. 17, p. 1042a; Sus 14; Jos., Bell. 1, 625; Ant. 8, 256). <span class=\"greek\">τὶ</span>, «alguma coisa» (POslo 17, 14 [136 d.C.], <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθές</span>; Cyranides, p. 100, 18, <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἔπραξεν</span>; Orig., C. Cels. 2, 11, 30, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἡμαρτημένον</span>). <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span>, «os pecados» (Jos., Ant. 8, 129; ver as inscrições em Steinleitner, n.os 13, 5; 23, 2; 24, 11; 25, 10), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:5</a> (cf. 1QS 1:24–26); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:16</a> (ver PAlthaus, Zahn Festgabe, 1928, 1ss); Hv 1, 1, 3; Hs 9, 23, 4. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, «confessar os pecados ao Senhor», Hv 3, 1, 5; cf. 6. <span class=\"greek\">τὰ</span> <span class=\"greek\">παραπτώματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐκκλησίᾳ</span>, «confessar as transgressões na congregação», D 4:14. <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παραπτωμάτων</span>, «fazer confissão das transgressões», 1Cl 51:3. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτίαις</span>, «pelos pecados», B 19:12. Uso absoluto: «fazer confissão de pecados», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:18</a>; 2Cl 8:3. Com dativo daquele a quem se confessam os pecados, 1Cl 52:1, 2 (com semelhança formal a Sl 7:18; 117:19 e passagens salmódicas semelhantes, mas não significa «louvar», por causa de 1Cl 51:3 [ver ④ abaixo]). — JSchnitzer, D. Beichte im Lichte d. Religionsgesch.: Ztschr. f. Völkerpsychol. 6, 1930, 94–105; RPettazzoni, La confessione dei Peccati II, 1935.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Declarar abertamente em reconhecimento: «professar, reconhecer», na voz média (PHib 30, acima; POxy 1473, 9; Lucian, Herm. 75); seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:11</a> (Is 45:23; ver ④ abaixo). — Nägeli 67.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">④</span> Dos significados «confessar» e «professar» surgiu, conforme demonstra Rtzst., Erlösungsmyst. 252, o sentido mais geral «louvar», em reconhecimento da beneficência e majestade divinas (assim, sobretudo na LXX; TestJob 40:2, <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span>); com dativo daquele que é louvado (frequentemente na LXX; TestSol 1:5; Philo, Leg. All. 1, 80): <span class=\"greek\">σοί</span> (2Km 22:50; 1Cr 29:13; Sl 85:12; 117:28 e outros; Did., Gen. 60, 20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a> = <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:21</a> (ver Norden, Agn. Th. 277–308; JWeiss, GHeinrici Festschr. 1914, 120ss; TArvedson, D. Mysterium Chr. [<a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>–30], 1937; NWilliams, ET 51, 1940, 182–86; 215–20; AHunter, NTS 8, 1962, 241–49); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:9</a> (Sl 17:50); 1Cl 26:2; 61:3; B 6:16 (cf. Sl 34:18). <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (Tob 14:7; Philo, Leg. All. 2, 95), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:11</a> (Is 45:23); <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> (desde Gn 29:35, frequente na LXX), 1Cl 48:2 (Sl 117:19); Hm 10, 3, 2. — DELG, s.v. <span class=\"greek\">ὁμός</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article id=\"entry-exomologesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξομολόγησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exomológēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξομολόγησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (Dionys. Hal.; Plut.; JosAs; Philo, Leg. All. 1, 82; Jos., Bell. 5, 435; Theoph. Ant. 2, 29 [p. 170, 17; com <span class=\"greek\">μετάνοια</span>]); ver a acepção ④ do verbete anterior: «louvor a Deus» (assim na LXX; «reconhecimento, profissão», em PsSol; título de JosAs e 15:2). A respeito de homens ricos: <span class=\"greek\">λίαν</span> <span class=\"greek\">μικρὰν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>., «tem um louvor muito pequeno», Hs 2:5; devido à proximidade de <span class=\"greek\">ἔντευξις</span> = «oração intercessória», talvez <span class=\"greek\">ἐ</span>. adquira aqui o sentido mais especializado de «oração de ação de graças» (ver MDibelius, Hdb. sobre Hs 2:5 [cf. m 10, 3, 2 <span class=\"greek\">ἐξομολογούμενος</span>]). — TW.</p></section></article>\n<article id=\"entry-exon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξόν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exón⟧</span><span class=\"separator\">·</span><span>forma flexionada; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξόν</span>: ver <span class=\"greek\">ἔξεστιν</span> 4.</p></section></article>\n<article id=\"entry-exorizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exorízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξορίζω</span>; primeiro aoristo <span class=\"greek\">ἐζώρισα</span>; passivo, primeira pessoa do plural, <span class=\"greek\">ἐζωρίσθημεν</span>, 1Macc 1:11, variante (Eur., Pla.; ICypr 135, 11; PRyl 75, 33 e 37; também 2Km 8:4 Aq; TestGad 6:3; GrBar 4:10; ApcSed 5:3; 6:7; Philo, Det. Pot. 142; Joseph.; Tat. 20, 1): «excluir, banir»; <span class=\"greek\">ἐ</span>. <span class=\"greek\">με</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ναοῦ</span>, «banir-me do templo», GJs 3:1.</p></section></article>\n<article id=\"entry-exorkizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορκίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exorkízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξορκίζω</span>; futuros <span class=\"greek\">ἐξορκιῶ</span> e <span class=\"greek\">ἐξορκίσω</span>, Gn 24:3; primeiro aoristo, segunda pessoa do singular, <span class=\"greek\">ἐξώρκισας</span>, Jz 17:2 A (ver <span class=\"greek\">ὁρκίζω</span>; Demosth. e outros; inscrições, papiros; TestSol; PFouad 203, 16; Jos., Ant. 2, 200; 11, 145; geralmente = <span class=\"greek\">ἐξορκόω</span>, «fazer alguém jurar»).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Obrigar alguém a fazer alguma coisa mediante a invocação de um poder transcendente: «ordenar solenemente» (assim POslo 148, 10 [séc. II/I a.C.], <span class=\"greek\">ἐξορκίζω</span>; IDefixWünsch 4, 1ss [séc. III d.C.]; PGM 3, 10; 119; 4, 1239, <span class=\"greek\">ἐξορκίζω</span> <span class=\"greek\">σε</span> <span class=\"greek\">δαῖμον</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>; 12, 137; amuleto em BGU 956, 1 [séc. III d.C.], <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁγίου</span> <span class=\"greek\">ὀνόματος</span>; cf. 3Km 22:16; Just., D. 85, 3, <span class=\"greek\">κατὰ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ὀνόματος</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Ἀβραάμ</span> e outros); acerca da expulsão de espírito maligno: «exorcizar um espírito maligno», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:13</a>, variante; 19:14, variante.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Submeter alguém a juramento para garantir a verdade daquilo que se diz: «tomar juramento, conjurar»; <span class=\"greek\">τινά</span>, «alguém»; <span class=\"greek\">ἐ</span>. <span class=\"greek\">σε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (com <span class=\"greek\">κατά</span>, como acima), «eu te conjuro por Deus», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a> (seguido de <span class=\"greek\">ἵνα</span>, como em Cyranides, p. 120, 3; sobre a adjuração na tradição judaica, ver Mishná: Shebuoth). — DELG, s.v. <span class=\"greek\">ὅρκος</span>. M-M. TW.</p></section></article>\n<article id=\"entry-exorkistes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορκιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exorkistḗs⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξορκιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>: «aquele que expulsa espíritos malignos invocando entidades transcendentes, exorcista» (assim epigrama de Lucian em Anth. Pal. 11, 427; Ptolem., Apotelesm. 4, 4, 10 Boll-B.); dos exorcistas judeus itinerantes, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:13</a>. Quanto à ideia, cf. Jos., Ant. 8, 42ss, especialmente 45: Salomão como autor de <span class=\"greek\">τρόποι</span> <span class=\"greek\">ἐξορκώσεων</span>, métodos de exorcismo que expulsam espíritos malignos. — WHeitmüller, «Im Namen Jesu», 1903, índice III. — DELG, s.v. <span class=\"greek\">ὅρκος</span>. TW.</p></section></article>\n<article id=\"entry-exorysso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορύσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exorýssō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξορύσσω</span>; primeiro aoristo <span class=\"greek\">ἐξώρυξα</span> (ver <span class=\"greek\">ὀρύσσω</span>; Hdt. e outros; PHal 1, 100 e 109 [séc. III a.C.]; LXX; Philo; Joseph.): «extrair alguma coisa à força de determinado lugar».</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> De olhos: «arrancar» (assim Hdt. 8, 116; Plut., Artox. 1018 [14, 10]; Lucian, D. Deor. 1, 1; Jos., Ant. 6, 71; 1Km 11:2; Jz 16:21 A), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:15</a> (o olho como membro precioso: Aeschyl., Sept. 530; Moschus 4, 9; Callim., H. 3, 211; Artem. 1, 25; Heliod. 2, 16, 4: o amado é <span class=\"greek\">ὀφθαλμὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐμαυτῆς</span>; Eustath. Macremb. 6, 10, <span class=\"greek\">Ζεῦ</span> <span class=\"greek\">Πάτερ</span>, <span class=\"greek\">μή</span> <span class=\"greek\">μου</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">ἐκκόψῃς</span>. Sobre o tema de sacrificar os olhos em favor de outros, ver Lucian, Tox.; Betz, Hermeneia Gal. ad loc.). — JBligh, TU 102, 1968, 382s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> De um telhado: «cavar através, abrir um buraco», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:4</a>, provavelmente em referência à abertura feita por escavação através da argila de que era feito o telhado (ABertholet, Kulturgesch. Israels, 1920, 122; CMcCown, JBL 58, 1939, 213–16; BHHW I 311), deixando os detritos de lado (<span class=\"greek\">ἐ</span>., em referência a detritos escavados, Hdt. 2, 150; 7, 23), de modo que não caiam sobre a cabeça daqueles que estão dentro da casa. — Ver <span class=\"greek\">στέγη</span>. — M-M.</p></section></article>\n<article id=\"entry-exoudeneo-exoudenoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουδενέω/ἐξουδενόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exoudenéō / exoudenóō⟧</span><span class=\"separator\">·</span><span>verbos; variantes gráficas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουδενέω</span>/<span class=\"greek\">ἐξουδενόω</span>; futuro <span class=\"greek\">ἐξουδενήσω</span>, -<span class=\"greek\">ώσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξουδένησα</span>, <span class=\"greek\">ἐξουδένωσα</span>; perfeito <span class=\"greek\">ἐξουδένηκα</span>, -<span class=\"greek\">ωκα</span>, LXX. Passivo: futuro, terceira pessoa do plural, <span class=\"greek\">ἐξουδενωθήσονται</span>, Sl 57:8; primeiro aoristo <span class=\"greek\">ἐξουδενήθην</span> (<span class=\"greek\">ἐξουδενώθην</span>); perfeito <span class=\"greek\">ἐξουδένωμαι</span>, LXX. (<span class=\"greek\">ἐξουδενέω</span>: Vi. Aesopi W 77b, p. 96, 37 P.; BGU 1117, 31s [13 a.C.] = Mitt-Wilck. II/2, 107, 31s; PMich 477, 23 [séc. II d.C.]. <span class=\"greek\">ἐξουδενόω</span>: Jó 30:1; PsSol 2:26 <span class=\"greek\">ἐξουδενωμένον</span>; Test12Patr; JosAs 6:6 [também no códice A]; Just., D. 101, 2 [códice A, -<span class=\"greek\">θένω</span> — Otto]; Sb 7524, 11 [249 a.C.?]; papiros: APF 11, 1935, 125 [séc. II a.C.]; Syntipas, p. 78, 15; escólio sobre Lucian, p. 279, 10 Rabe). Os manuscritos do NT variam (sobre a grafia, ver Phryn., p. 182 Lob.; B-D-F §33 e 108, 2, apêndice; Mlt-H. 111s; 310; 396; para a LXX, Thackeray 105). Literalmente, «fazer de alguém ou de alguma coisa um <span class=\"greek\">οὐδείς</span>/<span class=\"greek\">οὐδέν</span>», isto é, «tratar com desprezo ou escárnio». <span class=\"greek\">ἐξουδενέω</span> (4Km 19:21), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:10</a>, variante; <span class=\"greek\">ἐξουδενόω</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:12</a>, variante; ver <span class=\"greek\">ἐξουθενέω</span>. — DELG, s.v. <span class=\"greek\">ὀρύσσω</span>. M-M.</p></section></article>\n<article id=\"entry-exoutheneo-exouthenoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουθενέω/ἐξουθενόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exouthenéō / exouthenóō⟧</span><span class=\"separator\">·</span><span>verbos; variantes gráficas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουθενέω</span>/<span class=\"greek\">ἐξουθενόω</span> (ver verbete anterior); futuro <span class=\"greek\">ἐξουθενήσω</span>, -<span class=\"greek\">ωσω</span>, LXX; primeiro aoristo <span class=\"greek\">ἐξουθένησα</span>, -<span class=\"greek\">ωσα</span>; perfeito <span class=\"greek\">ἐξουθένηκα</span>, -<span class=\"greek\">ωκα</span>, LXX. Passivo: primeiro aoristo <span class=\"greek\">ἐξουθενήθην</span>, -<span class=\"greek\">ώθην</span>; perfeito <span class=\"greek\">ἐξουθένημαι</span>, particípio <span class=\"greek\">ἐξουθηνημένος</span>, LXX; <span class=\"greek\">ἐξουθενωμένοι</span> (somente em TestAsh 7:2, junto de <span class=\"greek\">ἐξουδενωμένοι</span>). (<span class=\"greek\">ἐξουθενέω</span>: Herodian, Gr. II 508, 10; Just.; Cass. Dio 7, 8, 8; En 99:14 [particípio presente]; Vi. Aesopi G 80, p. 60, duas últimas linhas P., <span class=\"greek\">ἐξουθενηθείς</span>; Vi. Aesopi W 77b, p. 97, 2 P., <span class=\"greek\">ἐξουθένησας</span> [ao lado de p. 96, 37 <span class=\"greek\">ἐξουδενῆσαι</span>]; escólio sobre Pla., Gorg. 483b; TestSol 22:5 P, <span class=\"greek\">ἐξουθενημένην</span>; JosAs 13:10, <span class=\"greek\">ἐξουθένηκα</span>; 2:1 [particípio presente]. <span class=\"greek\">ἐξουθενόω</span>: Rhet. Gr. I 623, 27; PsSol 2:5 e 27; En 99:14, particípio presente; TestLevi 16:2; TestAsh 7:2; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:12</a>, variante; 1Cl 18:17 = Sl 50:19. Sobre a grafia, ver New Docs 2, 83 e as referências em <span class=\"greek\">ἐξουδενέω</span>.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Demonstrar, pela atitude ou pelo modo de tratamento, que uma entidade carece de mérito ou valor: «desprezar». <span class=\"greek\">τινά</span>, «alguém» (Ps.-Callisth., p. 72, 19; Achmes 128, 10; escólio sobre Soph., Ajax 368, p. 36 Papag. [1888]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:9</a> (Field, Notes 72); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:3</a>, 10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:11</a>; <span class=\"greek\">σὺ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">ἐξουθενῶν</span> <span class=\"greek\">αὐτήν</span>, «quem és tu, afinal, para desprezá-la?», GMary 463, 23. <span class=\"greek\">τὶ</span>, «alguma coisa» (Jos., Bell. 6, 315; passivo: Philo, Leg. All. 2, 67), 1Cl 18:17 (Sl 50:19). <span class=\"greek\">ἐξουθενημένος</span>, «desprezado, sem importância»; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐ</span>. (Philo, Mos. 2, 241; Just., D. 121, 3, <span class=\"greek\">παρουσίᾳ</span>; 131, 2, <span class=\"greek\">μυστηρίου</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:4</a>; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:28</a>. Acerca da capacidade de falar do apóstolo quando se apresenta pessoalmente (em paralelo a <span class=\"greek\">ἀσθενής</span>): «não vale nada», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:10</a>. A expressão <span class=\"greek\">τ</span>. <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σαρκί</span> <span class=\"greek\">μου</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξουθενήσατε</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:14</a>, contém dois componentes principais: «Minha debilidade física de fato vos afligiu» e «Não me desprezastes por causa dela». O acusativo na expressão <span class=\"greek\">τ</span>. <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">ὑμῶν</span> é provavelmente temporal, e o verbo final é usado absolutamente; o pensamento pode traduzir-se: «durante vosso tempo de provação em relação à minha deficiência física, não demonstrastes desprezo». (Ver ②.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Não querer ter relação com alguma coisa por considerá-la indigna de consideração: «rejeitar com desprezo» (1Km 8:7; PsSol 2:5; En 99:14). Assim, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:20</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:11</a>. — Bauer observou que, pelo menos para <span class=\"greek\">διαπτύω</span> <span class=\"greek\">τι</span>, o significado «rejeitar alguma coisa» está bem estabelecido (Dositheus, Ars Gramm. 68, 10 Tolk.: <span class=\"greek\">διέπτυσεν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἱκετείας</span>), e o mesmo se aplica a <span class=\"greek\">περιπτύω</span> (Simplicius em Epict., p. 58, 8; 61, 20; 98, 36; 119, 18). Sugeriu que <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:14</a> poderia traduzir-se: «Não me tratastes com desprezo nem rejeitastes a tentação que minha aparência física poderia ter representado para vós». (Ver ①.)</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Considerar outra pessoa sem importância e, portanto, digna de maus-tratos (= <span class=\"greek\">ἐξουδενέω</span>): «tratar com desprezo» (Just., A I, 63, 16, <span class=\"greek\">ἐξουθενηθῆναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παθεῖν</span>); <span class=\"greek\">τινά</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:11</a>; B 7:9. Passivo: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:12</a>, variante. — DELG, s.v. <span class=\"greek\">οὐ</span>. M-M.</p></section></article>\n<article id=\"entry-exouthenema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουθένημα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exouthénēma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουθένημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (ver os dois verbetes anteriores): «coisa desprezada». <span class=\"greek\">ἐγώ</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">λαοῦ</span>, «sou objeto de desprezo do povo», 1Cl 16:15 (Sl 21:7, variante [ARahlfs, Psalmi cum Odis, 1931, ad loc.]).</p></section></article>\n<article id=\"entry-exousia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exousía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξουσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Soph., Thu. e posteriores; inscrições, papiros, LXX, En, pseudepígrafos, Philo, Joseph., Just.; Tat. 30, 1; Mel., P. 104, 810 [Bodm.]); derivado de <span class=\"greek\">ἔξεστιν</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Estado de controle sobre alguma coisa: «liberdade de escolha, direito» (por exemplo, o «direito» de agir, decidir ou dispor da própria propriedade como se desejar: BGU 1158, 13 [9 a.C.] = Mitt-Wilck. II/2, 234, 13; termo técnico jurídico, especialmente em testamentos: POxy 272, 13; BGU 183, 25, <span class=\"greek\">ἔχειν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span> <span class=\"greek\">πάντων</span>; PTebt 319, 21. — Sir 30:11). <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span>, «ter o direito», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 3:9</a> (Just., D. 16, 4). Seguido de infinitivo (Teles, p. 23, 14; 24, 11; Tob 2:13 S; 7:10 S), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:18</a>; 1Co 9:4ss; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:5</a>; B 4:2. Seguido de genitivo objetivo (<span class=\"greek\">τίς</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐξουσίαν</span>; Epict. 3, 24, 70; <span class=\"greek\">διδόναι</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πετεινῶν</span>, Did., Gen. 61, 24): <span class=\"greek\">εἰ</span> <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">μετέχουσι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:12</a>. Também <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ξύλον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>, «o direito à árvore da vida», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:14</a>. Com verbos de duas construções: <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κεραμεὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πηλοῦ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">φυράματος</span>, «o oleiro tem direito sobre o barro, de fazer [algo] da mesma massa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:21</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (4Macc 4:5), «estar livre em relação a alguma coisa» (oposto a <span class=\"greek\">ἀνάγκην</span> <span class=\"greek\">ἔχειν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:37</a>; cf. 8:9; <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐαγγελίῳ</span>, «direito no evangelho», 9:18. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σῇ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὑπῆρχεν</span>, «estava à tua disposição», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:4</a> (Esth 4:17b; Appian, Liby. 52 §226, <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">εἶναι</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> = «alguma coisa estar à disposição de alguém, estar em seu poder»).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Potencial ou recurso para comandar, controlar ou governar: «capacidade, força, poder» (quanto à capacidade de fazer alguma coisa, cf. Did., Gen. 162, 5: <span class=\"greek\">ἡ</span> <span class=\"greek\">προσαιρέσεως</span> <span class=\"greek\">ἐξουσία</span>; cf. 1Esdr 4:28, 40; 2Macc 7:16: o rei pode fazer o que lhe agrada, porque tem capacidade para isso). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἵππων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στόματι</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐστιν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:19</a>; cf. v. 3; 13:2, 4; 18:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:8</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:19</a>. Seguido de infinitivo para indicar o que alguém consegue fazer (En 25:4, <span class=\"greek\">ἅψασθαι</span>; Diod S 4, 52, 4, <span class=\"greek\">ἀμύνασθαι</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">ἐξουσίαν</span>; Mel., P. 104 [B], <span class=\"greek\">πάντα</span> <span class=\"greek\">κρίνει</span>): <span class=\"greek\">ἐκβάλλειν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δαιμόνια</span>, «expulsar os demônios», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:15</a>; <span class=\"greek\">ἐμβαλεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γέενναν</span>, «lançar na geena», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:5</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:12</a>; 7:1, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:10</a>; 11:6. Seguido de genitivo do infinitivo: <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατεῖν</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">ὄφεων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:19</a>; <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ἐ</span>., «exercer poder», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:12</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινός</span>, «ter poder sobre alguém» (Epict. 4, 12, 8), GPt 3:7; <span class=\"greek\">ἑαυτοῦ</span>, IPol 7:3; também <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:6</a>; cf. AcPl Ha 1, 3. Especialmente do poder de Deus (Theodor. Prodr. 5, 313, <span class=\"greek\">ἡ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐ</span>.; Dn 4:17; Jos., Ant. 5, 109; 18, 214), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:5</a> (cf. 2Cl 5:4); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:7</a>; Jd 25; Hs 9, 23, 4. <span class=\"greek\">πάντων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐξουσίαν</span>, «poder sobre todos», Hm 4, 1, 11; Hs 9, 28, 8; <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>., 5, 7, 3 (En 9:5); <span class=\"greek\">τὴν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐ</span>., MPol 2:1; <span class=\"greek\">τέλους</span> <span class=\"greek\">ἐ</span>., «poder sobre o fim», PtK 2, p. 13, 22; <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πληγάς</span>, «controle sobre as pragas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:9</a>. Também do poder de Satanás, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:18</a>; final de Marcos no manuscrito Freer; B 2:1. — O poder procedente de Deus pode envolver conhecimento transcendente, e ambos podem ser expressos por <span class=\"greek\">ἐ</span>. (Herm. Wr. 1, 13; 14; 32). Assim, os ouvintes de Jesus concluem, pelo seu ensino, que ele necessariamente possui <span class=\"greek\">ἐ</span>. (isto é, ele não precisa primeiro perguntar o que a prática ou interpretação tradicional exige), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:22</a> («licença» de um mestre judaico, L-S-J-M Suppl., 1968; contra isso, AArgyle, ET 80, 1968/69, 343); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:29</a> (Rtzst., Poim. 48, 3; Mysterienrel.³ 302; 363; JStarr, HTR 23, 1930, 302–5; HWindisch, Pls. u. Christus, 1934, 151ss; DDaube, JTS 39, 1938, 45–59; HFlowers, ET 66, 1955, 254 [«como um rei»]; DHudson, ET 67, 1955/56, 17; JCoutts, JTS 8, 1957, 111–18 [Jesus e os Doze]). As expressões preposicionais <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐξουσίαν</span>, «de acordo com conhecimento e poder», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:27</a>, e <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:32</a>, pertencem a esta classificação; cf. 4:36. A estreita relação entre <span class=\"greek\">ἐ</span>. e «gnose» e ensino também em B 18:1. — Mas nem sempre é possível traçar uma distinção nítida entre este sentido e</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> O direito de controlar ou comandar: «autoridade, poder absoluto, autorização» (Sextus 36: o <span class=\"greek\">πιστός</span> recebe <span class=\"greek\">ἐ</span>. de Deus). <span class=\"greek\">ἐ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιτροπή</span> (cf. Ps.-Pla., Defin. p. 415c, <span class=\"greek\">ἐξουσία</span>, <span class=\"greek\">ἐπιτροπὴ</span> <span class=\"greek\">νόμου</span>), «autoridade e incumbência», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:12</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ποίᾳ</span> <span class=\"greek\">ἐξουσίᾳ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ποιεῖς</span>; «com que autoridade fazes estas coisas?», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:23</a>, 24, 27; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:28</a>, 29, 33; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:2</a>, 8. <span class=\"greek\">ἐ</span>. <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινί</span>, «colocar alguém no comando» (Diod S 13, 36, 2; 14, 81, 6; cf. Vi. Aesopi G 11, p. 39, 6 P.; En 9:7; TestJob 3:6; Jos., Ant. 2, 90; 20, 193), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:34</a>; PtK 2, p. 14, 13. <span class=\"greek\">οἷς</span> <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐ</span>., «a quem ele concedeu direitos sobre o evangelho [para proclamá-lo]», B 8:3. <span class=\"greek\">ὅτι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄρχειν</span> <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">ἐστίν</span>, «porque governar depende de autoridade», B 6:18. Da autoridade apostólica, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:8</a>; 13:10; ISm 4:1. Da autoridade total de Jesus, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:18</a> (cf. Herm. Wr. 1, 32; Dn 7:14; DStanley, CBQ 29, 1967, 555–73); Hs 5, 6, 1. Com genitivo daquele que tem autoridade: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:10</a> (Just., A I, 40, 7). Com genitivo daquilo sobre que a autoridade é exercida (Diod S 2, 27, 3; IDefixWünsch 4, 21; Sl 135:8, 9; Wsd 10:14; Sir 17:2; Jos., Vi. 190): <span class=\"greek\">ἐ</span>. <span class=\"greek\">πνευμάτων</span> <span class=\"greek\">ἀκαθάρτων</span>, «sobre os espíritos imundos», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:7</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17:2</a>; Hm 4, 3, 5; PtK 2, p. 14, 13; 1Cl 61:2; ISm 4:1; <span class=\"greek\">τούτου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, Hs 8, 3, 3. Também <span class=\"greek\">ἐπί</span> com acusativo (cf. Sir 33:20), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:1</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:8</a>; 13:7. Igualmente <span class=\"greek\">ἐπί</span> com genitivo (cf. Dn 3:97), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:26</a>; 11:6b; 14:18. <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> (também <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, Orig., C. Cels. 2, 13, 56) indica a origem da autoridade (ver <span class=\"greek\">παρά</span> A3b), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:14</a>; 26:10; Hs 5, 6, 4 (restaurado do latim; <span class=\"greek\">ἐ</span>. <span class=\"greek\">λαμβάνειν</span>, como Diod S 11, 42, 6; TestJob 8:2s; 16:4; Vi. Aesopi G 11, p. 39, 4 P.); e <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> indica aquele contra quem ela se dirige (TestJob 16:2, <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐμοῦ</span>; 8:2, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπαρχόντων</span> <span class=\"greek\">μου</span>, «sobre minhas posses»; Sb 8316, 6s, <span class=\"greek\">κύριε</span> <span class=\"greek\">Σάραπι</span> <span class=\"greek\">δὸς</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κατεξουσίαν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐχθρῶν</span> <span class=\"greek\">αὐτοῦ</span>; Orig., C. Cels. 7, 43, 25), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:11</a> (HvCampenhausen, TLZ 73, 1948, 387–92); B 4:13. Seguido de infinitivo presente (cf. X., Mem. 2, 6, 24 e 35; Diod S 12, 75, 4; 1Macc 10:35; 11:58; Jos., Ant. 4, 247), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:6</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:24</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:27</a>. Seguido de infinitivo aoristo (Jdth 8:15; 1Esdr 8:22; 1Macc 1:13), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:10</a>. Seguido de genitivo do infinitivo presente (4Macc 5:15), Hm 12, 4, 2. — RDillon, «As One Having Authority» (Mark 1:22): CBQ 57, 1995, 92–113.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">④</span> Poder exercido por governantes ou por outras pessoas de posição elevada em virtude de seu cargo: «poder governante, poder oficial» (Ps.-Pla., Alc. 1, 135b e outros; LXX; Jos., Bell. 2, 140; Vi. 80). <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">βασιλεύς</span>, «autoridade como rei», Ap 17:12s (Diod S 2, 45, 1, <span class=\"greek\">βασιλικὴν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span>; 14, 32, 5, <span class=\"greek\">ἐ</span>. <span class=\"greek\">λαμβάνειν</span>); <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἡγεμόνος</span>, «autoridade do governador», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:20</a>; cf. Jo 19:10s, ver ③ acima. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">πόλεων</span>, «autoridade sobre dez cidades», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:17</a>. <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τασσόμενος</span>, «homem sujeito à autoridade», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:8</a> (MFrost, ET 45, 1934, 477s); cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:9</a>; Hs 1:3. — Poder próprio de determinado cargo (Diod S 1, 70, 1; 14, 113, 6, <span class=\"greek\">ἡ</span> <span class=\"greek\">ὑπατικὴ</span> <span class=\"greek\">ἐξουσία</span>; Plut., Mar. 406 [2, 1], Caes. 734 [58, 1]): <span class=\"greek\">ἐπαρχικὴ</span> <span class=\"greek\">ἐ</span>., «poder de um prefeito», subscrição de Fm.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">⑤</span> Aquele que é portador de autoridade governante.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Autoridades humanas: «funcionários, governo» (Dionys. Hal. 8, 44; 11, 32; POxy 261, 15), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:11</a> (aqui e em outros lugares do NT com <span class=\"greek\">ἀρχή</span>, como também em Pla.); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:1</a>, 2, 3 (quanto a 13:1b, cf. a expressão «dito antigo» [ver Hes., Theogony 96, <span class=\"greek\">ἐκ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">βασιλῆες</span>; sobre isso, HFränkel, Dichtung u. Philos. des frühen Griechentums, 1962, 111, n. 6], em Artem. 2, 36, p. 135, 24; 2, 69, p. 161, 17, <span class=\"greek\">τὸ</span> <span class=\"greek\">κρατοῦν</span> <span class=\"greek\">δύναμιν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">θεοῦ</span> = «o poder governante possui sua autoridade de Deus»; Wsd 6:3; Jos., Bell. 2, 140, <span class=\"greek\">οὐ</span> <span class=\"greek\">δίχα</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">περιγενέσθαι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄρχειν</span> … <span class=\"greek\">ἐξουσίαν</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:1</a>. Quanto à opinião de que as <span class=\"greek\">ἐ</span>. de Rm 13 sejam poderes espirituais, como em ⓑ abaixo, ver OCullmann, Christ and Time (trad. Filson), 1950, 191–210. — Sobre o assunto em geral, ver LGaugusch, D. Staatslehre d. Ap. Pls nach Ro 13: ThGl 5, 1934, 529–50; JUitman, Onder Eig. Vaandel 15, 1940, 102–21; HvCampenhausen, ABertholet Festschr. 1950, 97–113; OCullmann, Zur neuesten Diskussion über die <span class=\"greek\">ἐξουσίαι</span> in Rö 13:1: TZ 10, 1954, 321–36; D. Staat im NT, 1961² (tradução inglesa The State in the NT, 1956, 93–114); contra ele, AStrobel, ZNW 47, 1956, 67–93. — GCaird, Princip. and Powers, 1956; RMorgenthaler, TZ 12, 1956, 289–304; CMorrison, The Powers That Be, 1960; EBarnikol, Rö 13. Der nichtpaulinische Ursprung der absoluten Obrigkeitsbejahung v. Rö 13:1–7, 1961, 65–133; HSchlier, Principalities and Powers in the NT, 1961 (trad. inglesa); MBorg, NTS 19, 1972/73, 205–18. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἀχθέντες</span>, «aqueles que são levados perante as autoridades», Hs 9, 28, 4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Dos governantes e dignitários transcendentes: «poderes do mundo espiritual» (TestLevi 3:8; TestSol 20:15 B); no singular (com <span class=\"greek\">ἀρχή</span> e <span class=\"greek\">δύναμις</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:24</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:10</a>. No plural (com <span class=\"greek\">ἀρχαί</span>, como em Just., D. 41, 1; cf. Orig., C. Cels. 4, 29, 22), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:10</a>; 6:12; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:16</a>; 2:15; (com <span class=\"greek\">ἄγγελοι</span>, <span class=\"greek\">δυνάμεις</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:22</a>. Cf. a variante de leitura para <span class=\"greek\">ἄρχειν</span>, Papias (4).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">⑥</span> A esfera em que se exerce o poder: «domínio» (4Km 20:13; Sl 113:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:6</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">Ἡρῴδου</span> <span class=\"greek\">ἐστίν</span>, «ele provém da jurisdição de Herodes», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:7</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span>, «domínio das trevas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:53</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:13</a> (em oposição à <span class=\"greek\">βασιλεία</span> de Cristo). Daí <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀέρος</span>, simplesmente «domínio do ar», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:2</a>; ver <span class=\"greek\">ἀήρ</span> 2b.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">⑦</span> Há diversas opiniões acerca do significado de <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:10</a>, <span class=\"greek\">ὀφείλει</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀγγέλους</span>. Atualmente, muitos entendem <span class=\"greek\">ἐξουσία</span> como «um meio de exercer poder» (cf. <span class=\"greek\">δύναμις</span> 1b. — Trata-se do abstrato pelo concreto, como <span class=\"greek\">βασιλεία</span> [1] em Diod S 1, 47, 5: uma figura de pedra <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> = «que traz três símbolos do poder real [diademas] sobre a cabeça»); isto é, o véu (<span class=\"greek\">κάλυμμα</span> é variante de leitura para <span class=\"greek\">ἐ</span>. nesta passagem; ver o aparato crítico em N.), pelo qual as mulheres em oração (quando se aproximam da esfera celestial) se protegem dos olhares amorosos de certos anjos. Mas o véu também pode ter sido simplesmente um símbolo de dignidade feminina, particularmente apropriado à mulher cristã, sobretudo na presença dos santos anjos (ver Cadbury abaixo). — WWeber, ZWT 46, 1903, 487–99; Dibelius, Geisterwelt 12–23 e outros; EFehrle, Die kultische Keuschheit im Altertum, 1910, 39; RPerdelwitz, StKr 86, 1913, 611–13; LBrun, ZNW 14, 1913, 298–308; GKittel, Rabbinica, 1920, 17ss; Billerb. III 423–35; KBornhäuser, NKZ 41, 1930, 475–88; WFoerster, ZNW 30, 1931, 185s; MGinsburger, RHPR 12, 1932, 245–47; OMotta, ET 44, 1933, 139–41; CSpicq, RB 48, 1939, 557–62; EBlakeney, ET 55, 1944, 138; SLösch, TQ 127, 1947, 216–61; JFitzmyer, NTS 3, 1957, 48–58; HCadbury, HTR 51, 1958, 1s (paralelos de Qumran); MHooker, NTS 10, 1964, 410–16; AIsaksson, Marriage and Ministry in the NT, 1965, 176–81; GSchwartz, ZNW 70, 1979, 249 (contexto aramaico). — LCerfaux et JTondriau, Un Concurrent du Christianisme, 1957. Ver <span class=\"greek\">ἄγγελος</span> 2c. — Variante de leitura para <span class=\"greek\">ἄρχειν</span>, Papias (4). — DELG, s.v. <span class=\"greek\">εἰμί</span>. New Docs 2, 83s. M-M. EDNT. TW. Sv.</p></section></article>"};
